/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: status, active, mount
 *   Constants: trackId, token
 * Tests
 *   - renders nothing while the feature is disabled or for an Audio MediaTrack
 *   - uploads a chosen clip as one bounded multipart request bound to the current source and revision
 *   - an outdated preview is explained, and Remove sends the current revision
 *   - unfinished work offers Reconcile and blocks upload while a live lease protects it
 * @end-catalog */

import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { cleanup, render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { json, session, viewer } from './adminFixtures.testSupport';
import { MotionPreviewPanel } from './MotionPreviewPanel';

const trackId = '111111111111111111111111';
const token = 'f'.repeat(32);
const status = (overrides: Record<string, unknown> = {}) => ({
  eligible: true, sourceToken: token, revision: 2, active: null, pending: null, cleanup: null, ...overrides
});
const active = (current = true) => ({
  revision: `pv_${'1'.repeat(32)}`, byteLength: 900000, durationMs: 6400, width: 854, height: 480,
  current, updatedAt: '2026-10-18T00:00:00.000Z'
});

const mount = () => {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  client.setQueryData(['browser-session'], session);
  return render(<QueryClientProvider client={client}><MotionPreviewPanel id={trackId} /></QueryClientProvider>);
};

beforeEach(() => {
  adminWorkspace.reset();
  adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true });
  adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); });

test('renders nothing while the feature is disabled or for an Audio MediaTrack', async () => {
  const fetchMock = vi.fn(async () => json({ code: 'ADMIN_MOTION_PREVIEW_DISABLED' }, 404));
  vi.stubGlobal('fetch', fetchMock);
  const disabled = mount();
  await waitFor(() => expect(fetchMock).toHaveBeenCalled());
  await waitFor(() => expect(disabled.container).toBeEmptyDOMElement());
  disabled.unmount();

  vi.stubGlobal('fetch', vi.fn(async () => json(status({ eligible: false, sourceToken: null }))));
  const audio = mount();
  await waitFor(() => expect(audio.container).toBeEmptyDOMElement());
});

test('uploads a chosen clip as one bounded multipart request bound to the current source and revision', async () => {
  const user = userEvent.setup();
  const requests: Array<{ url: string; init?: RequestInit }> = [];
  let uploaded = false;
  vi.stubGlobal('fetch', vi.fn(async (url: string, init?: RequestInit) => {
    requests.push({ url, init });
    if (init?.method === 'POST') {
      uploaded = true;
      return json({ revision: `pv_${'1'.repeat(32)}`, durationMs: 6400, width: 854, height: 480, byteLength: 900000, cleanupPending: false }, 201);
    }
    return json(status(uploaded ? { revision: 6, active: active() } : {}));
  }));
  mount();

  expect(await screen.findByText('This Video has no motion preview.')).toBeInTheDocument();
  await user.upload(screen.getByLabelText('Preview clip (MP4)'), new File([new Uint8Array([1, 2, 3])], 'clip.mp4', { type: 'video/mp4' }));
  await user.click(screen.getByRole('button', { name: 'Upload preview' }));

  expect(await screen.findByText('The preview was uploaded.')).toBeInTheDocument();
  expect(await screen.findByText('Current preview: 6.4 s, 854 × 480.')).toBeInTheDocument();
  const post = requests.find((request) => request.init?.method === 'POST')!;
  expect(post.url).toBe(`/api/admin/v1/catalog/audioTrack/${trackId}/motion-preview`);
  const contentType = new Headers(post.init!.headers).get('Content-Type')!;
  expect(contentType).toMatch(/^multipart\/form-data; boundary=FinitudeMotionPreview-/);
  // JSDOM's Blob has no text(); FileReader reads the exact multipart envelope.
  const body = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.readAsText(post.init!.body as Blob);
  });
  expect(body).toContain(`name="sourceToken"\r\n\r\n${token}\r\n`);
  expect(body).toContain('name="expectedRevision"\r\n\r\n2\r\n');
  expect(body).toContain('name="motionPreviewFile"; filename="preview.mp4"\r\nContent-Type: video/mp4');
});

test('an outdated preview is explained, and Remove sends the current revision', async () => {
  const user = userEvent.setup();
  const requests: RequestInit[] = [];
  vi.stubGlobal('fetch', vi.fn(async (_url: string, init?: RequestInit) => {
    if (init?.method) requests.push(init);
    return init?.method === 'DELETE' ? json({ cleanupPending: false }) : json(status({ active: active(false) }));
  }));
  mount();

  expect(await screen.findByText(/made for an earlier Video and stays hidden/)).toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Remove preview' }));

  expect(await screen.findByText('The preview was removed.')).toBeInTheDocument();
  expect(requests[0].method).toBe('DELETE');
  expect(JSON.parse(String(requests[0].body))).toEqual({ expectedRevision: 2 });
});

test('unfinished work offers Reconcile and blocks upload while a live lease protects it', async () => {
  const user = userEvent.setup();
  const methods: string[] = [];
  vi.stubGlobal('fetch', vi.fn(async (url: string, init?: RequestInit) => {
    if (init?.method) methods.push(`${init.method} ${url.split('/motion-preview')[1]}`);
    if (url.endsWith('/reconcile')) return json({ cleanupPending: false });
    return json(status({ pending: { status: 'failed', outcomeUnknown: true, leaseActive: false } }));
  }));
  mount();

  expect(await screen.findByText(/Reconcile it before uploading again/)).toBeInTheDocument();
  await user.click(screen.getByRole('button', { name: 'Reconcile' }));
  expect(await screen.findByText('Unfinished preview work was reconciled.')).toBeInTheDocument();
  expect(methods).toEqual(['POST /reconcile']);
  cleanup();

  vi.stubGlobal('fetch', vi.fn(async () => json(status({ pending: { status: 'uploading', outcomeUnknown: true, leaseActive: true } }))));
  mount();
  expect(await screen.findByRole('button', { name: 'Upload preview' })).toBeDisabled();
  expect(screen.getByRole('button', { name: 'Reconcile' })).toBeDisabled();
});
